SummerlogdialogueLocalData.tab = {
[1001] = {dialogueid = 1001, picida = "Activity/Summer/Lihui_Sikadi", namea = "0", dialoguea = "領航，你想看看《影之國編年史》的外傳篇章嗎！是吾剛剛寫好的哦！那是講述吾與夥伴們，跟隨著預言，擊倒邪惡的龍王巴哈姆特的故事。", positionax = "-43", positionay = "-157", picidb = "Activity/Summer/Lihui_Ling", nameb = "0", dialogueb = "領航，鈴來找你玩咯，我已經準備好了，我們什麼時候出發呀？", positionbx = "-7", positionby = "-92", bgm = "29-another_summer", "0", "0", "0", "0"},
[1002] = {dialogueid = 1002, picida = "Activity/Summer/Lihui_Sikadi_yongzhuang", namea = "0", dialoguea = "先是遇上了跨越星空而來的，離家出走的魔女。", positionax = "31", positionay = "-194", picidb = "Activity/Summer/Lihui_Duoluoxi", nameb = "0", dialogueb = "啊呀，那這個角色就由我來飾演吧，不過我的衣服還沒來得及換呢。", positionbx = "170", positionby = "58", bgm = "29-another_summer", "0", "0", "0", "0"},
[1003] = {dialogueid = 1003, picida = "Activity/Summer/Lihui_Sikadi_yongzhuang", namea = "0", dialoguea = "然後是燦耀於世的偶像，她剛剛從冥府之國死而復生。", positionax = "31", positionay = "-170", picidb = "Activity/Summer/Lihui_Jieshuxi", nameb = "0", dialogueb = "咦咦？這說的是我？我原來死了一次嗎！？", positionbx = "37", positionby = "-270", bgm = "29-another_summer", "0", "0", "0", "0"},
[1004] = {dialogueid = 1004, picida = "Activity/Summer/Lihui_Sikadi_yongzhuang", namea = "0", dialoguea = "旅途中的影之國女王，正遭受著折磨，那是自她意識中誕生的邪惡意志！", positionax = "31", positionay = "-194", picidb = "Activity/Summer/Lihui_Huizhang", nameb = "0", dialogueb = "……？我嗎？", positionbx = "-29", positionby = "-335", bgm = "29-another_summer", "0", "0", "0", "0"},
[1005] = {dialogueid = 1005, picida = "Activity/Summer/Lihui_Sikadi_yongzhuang", namea = "0", dialoguea = "在與邪惡意志激戰的同時，邪惡意志的幫兇忽然登場！女王大危機！", positionax = "31", positionay = "-194", picidb = "Activity/Summer/Lihui_Wangnv", nameb = "0", dialogueb = "我難道不應該是善良的一面嗎！？", positionbx = "25", positionby = "-274", bgm = "29-another_summer", "0", "0", "0", "0"},
[1006] = {dialogueid = 1006, picida = "Activity/Summer/Lihui_Ling_yongzhuang", namea = "0", dialoguea = "是西瓜！領航也一起來吃吧？", positionax = "77", positionay = "-145", picidb = "Activity/Summer/Lihui_Sikadi_yongzhuang2", nameb = "0", dialogueb = "嗯……那就由吾來落刀吧！就用吾新學到的【斯卡蒂流帝王心劍術】！", positionbx = "39", positionby = "-189", bgm = "29-another_summer", "0", "0", "0", "0"},
[1101] = {dialogueid = 1101, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "多洛莉絲", dialoguea = "talk_9001400_90014", positionax = "7", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "斯卡蒂", dialogueb = "吾聽說是科學部的博士們準備的。", positionbx = "-21", positionby = "-133", bgm = "0", "0", "0", "0", "0"},
[1102] = {dialogueid = 1102, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "多洛莉絲", dialoguea = "talk_9001401_90014", positionax = "7", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "斯卡蒂", dialogueb = "亞爾薇特博士，紅博士和克莉絲蒂娜博士。", positionbx = "-21", positionby = "-133", bgm = "0", "0", "0", "0", "0"},
[1103] = {dialogueid = 1103, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "多洛莉絲", dialoguea = "talk_9001402_90014", positionax = "7", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "斯卡蒂", dialogueb = "……唔，好吧。", positionbx = "-21", positionby = "-133", bgm = "0", "0", "0", "0", "0"},
[1104] = {dialogueid = 1104, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "九十九環", dialoguea = "talk_9001403_90014", positionax = "0", positionay = "-171", picidb = "0", nameb = "0", dialogueb = "0", positionbx = "0", positionby = "0", bgm = "0", "0", "0", "0", "0"},
[1105] = {dialogueid = 1105, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "克莉絲蒂娜", dialoguea = "talk_9001404_90014", positionax = "-13", positionay = "-47", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "亞爾薇特", dialogueb = "很好，繼續記錄“夢想成真禮物箱”的資料。", positionbx = "-70", positionby = "-8", bgm = "0", "0", "0", "0", "0"},
[1010] = {dialogueid = 1010, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "羅莎琳德", dialoguea = "……這次是我們出場的話，難道說，我們是主人公？", positionax = "-25", positionay = "11", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "海蘿", dialogueb = "也可能是給主人公當墊腳石的炮灰噢？", positionbx = "-25", positionby = "15", bgm = "0", "0", "0", "0", "0"},
[1011] = {dialogueid = 1011, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "羅莎琳德", dialoguea = "我們隊伍到底有幾個人？", positionax = "-25", positionay = "11", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "海蘿", dialogueb = "說是有四個人，但搞不好只有羅莎你一個人誒。", positionbx = "-25", positionby = "15", bgm = "0", "0", "0", "0", "0"},
[1012] = {dialogueid = 1012, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "海蘿", dialoguea = "天氣好的時候就會想要躺在地上曬太陽，大家都是這樣吧？", positionax = "-25", positionay = "15", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "羅莎琳德", dialogueb = "不，只有你會這麼做。", positionbx = "-25", positionby = "11", bgm = "0", "0", "0", "0", "0"},
[1013] = {dialogueid = 1013, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "海蘿", dialoguea = "說起來，方舟附近會有原罪出現嗎？", positionax = "-25", positionay = "15", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "羅莎琳德", dialogueb = "如果有的話，感覺就像是被投放到敵人大本營的炮灰一樣。", positionbx = "-25", positionby = "11", bgm = "0", "0", "0", "0", "0"},
[1014] = {dialogueid = 1014, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "星爍", dialoguea = "我還以為我這次不會出場了。", positionax = "-25", positionay = "12", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "羅莎琳德", dialogueb = "你是哪位……？", positionbx = "-25", positionby = "11", bgm = "0", "0", "0", "0", "0"},
[1021] = {dialogueid = 1021, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "希夏", dialoguea = "talk_9002300_90023", positionax = "-200", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "梅莉雅", dialogueb = "聖女梅莉雅也向你致以謝意~", positionbx = "-125", positionby = "-150", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1022] = {dialogueid = 1022, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "梅莉雅", dialoguea = "talk_9002302_90023", positionax = "-125", positionay = "-150", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "希夏", dialogueb = "這才第二天而已，你的能量用得也太快了吧……", positionbx = "-210", positionby = "-50", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1023] = {dialogueid = 1023, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "梅莉雅", dialoguea = "talk_9002304_90023", positionax = "-125", positionay = "-150", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "希夏", dialogueb = "你還挺節儉的嘛，可惜，不~行~", positionbx = "-210", positionby = "-50", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1024] = {dialogueid = 1024, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "希夏", dialoguea = "talk_9002306_90023", positionax = "-200", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "珂斯嘉德", dialogueb = "想著至少得抽空來一趟，總不能完全甩手不管。", positionbx = "40", positionby = "-32", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1025] = {dialogueid = 1025, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "梅莉雅", dialoguea = "talk_9002308_90023", positionax = "-125", positionay = "-150", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "珂斯嘉德", dialogueb = "這也只是因心而異，對我來說，能會見這位領航就已經值得了。", positionbx = "40", positionby = "-32", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1026] = {dialogueid = 1026, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "阿爾泰婭（塞繆）", dialoguea = "嗯……嗯……你是在COSPLAY嗎？", positionax = "-120", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "莉法", dialogueb = "不是，這個是……我的任務裝備。", positionbx = "-120", positionby = "-50", bgm = "75-Who_am_I", "0", "0", "0", "0"},
[1027] = {dialogueid = 1027, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "菲琳", dialoguea = "你好，我是菲琳·布蘭妮！", positionax = "-110", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "七實", dialogueb = "嗯？不是“聯合部隊隊員”嗎？", positionbx = "-100", positionby = "-50", bgm = "75-Who_am_I", "0", "0", "0", "0"},
[1028] = {dialogueid = 1028, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "七實", dialoguea = "你的紅頭髮是染的嗎？為了配合瞳色特意染的嗎？還是說是某種變身？", positionax = "-70", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui5", nameb = "阿爾泰婭（塞繆）", dialogueb = "是天生的！這是主人公的發色！", positionbx = "-125", positionby = "-70", bgm = "75-Who_am_I", "0", "0", "0", "0"},
[1029] = {dialogueid = 1029, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "七實", dialoguea = "戴上頭盔能讓人分辨不出來你是誰，但是一查聲優不就知道答案了嗎？", positionax = "-70", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "莉法", dialogueb = "這一點的確沒有考慮過呢……", positionbx = "-120", positionby = "-60", bgm = "75-Who_am_I", "0", "0", "0", "0"},
[1030] = {dialogueid = 1030, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "阿爾泰婭（塞繆）", dialoguea = "這是我的好朋友，阿爾泰婭·維斯。", positionax = "-120", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "阿爾泰婭（阿爾泰婭）", dialogueb = "……你在和誰說話呢？", positionbx = "-130", positionby = "-50", bgm = "75-Who_am_I", "0", "0", "0", "0"},
[1031] = {dialogueid = 1031, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "斯卡蒂", dialoguea = "talk_9002800_90028", positionax = "-60", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "莉莉絲", dialogueb = "沒想到你竟然能把這本書寫到2……", positionbx = "-25", positionby = "-50", bgm = "72-desertion_of_summer", "0", "0", "0", "0"},
[1032] = {dialogueid = 1032, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "斯卡蒂", dialoguea = "talk_9002801_90028", positionax = "-60", positionay = "-50", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "莉莉絲", dialogueb = "所以到底為什麼大家會穿著泳裝打來打去……", positionbx = "-25", positionby = "-50", bgm = "72-desertion_of_summer", "0", "0", "0", "0"},
[1033] = {dialogueid = 1033, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "奧菲莉亞", dialoguea = "talk_9002802_90028", positionax = "-25", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "未來", dialogueb = "好、好下流的肉體。", positionbx = "-25", positionby = "-70", bgm = "72-desertion_of_summer", "0", "0", "0", "0"},
[1034] = {dialogueid = 1034, picida = "Activity/ThreeChooseOne/Img_Lihui7", namea = "會長", dialoguea = "talk_9002803_90028", positionax = "-25", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui8", nameb = "王女", dialogueb = "嗯？難道不是來這裏的度假的嗎！", positionbx = "-25", positionby = "-60", bgm = "72-desertion_of_summer", "0", "0", "0", "0"},
[1035] = {dialogueid = 1035, picida = "Activity/ThreeChooseOne/Img_Lihui6", namea = "伊莎貝拉", dialoguea = "talk_9002804_90028", positionax = "90", positionay = "70", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "弗蘭卡", dialogueb = "這是我用私房錢買的哦。", positionbx = "-100", positionby = "-50", bgm = "72-desertion_of_summer", "0", "0", "0", "0"},
[1036] = {dialogueid = 1036, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "九十九環", dialoguea = "talk_9004100_90041", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui6", nameb = "Red", dialogueb = "你們的情書與欲望就由我收下了！", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1037] = {dialogueid = 1037, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "朱利烏斯", dialoguea = "talk_9004102_90041", positionax = "20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "查麗莎", dialogueb = "咦……你是誰，怎麼會在這裏！？", positionbx = "-20", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1038] = {dialogueid = 1038, picida = "Activity/ThreeChooseOne/Img_Lihui4", namea = "查麗莎", dialoguea = "talk_9004104_90041", positionax = "-45", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "朱利烏斯", dialogueb = "咳……我的名字是亞瑟·潘德拉貢！", positionbx = "0", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1039] = {dialogueid = 1039, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "紅博士", dialoguea = "talk_9004106_90041", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "九十九環", dialogueb = "呃啊啊啊啊——", positionbx = "-20", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1040] = {dialogueid = 1040, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "未来", dialoguea = "talk_9004108_90041", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "朱利烏斯", dialogueb = "我會盡綿薄之力輔佐您的。", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1041] = {dialogueid = 1041, picida = "Activity/ThreeChooseOne/Img_Lihui6", namea = "Red", dialoguea = "talk_9004110_90041", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "朱利烏斯", dialogueb = "所以原罪中的原罪為什麼要奪走大家的情書……", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1042] = {dialogueid = 1042, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "九十九環", dialoguea = "talk_9004112_90041", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "未来", dialogueb = "超級機械朱利烏斯號！？為什麼是朱利烏斯的名字……而且聽起來一點都不像是邪惡怪盜的秘密武器！？", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1043] = {dialogueid = 1043, picida = "Activity/ThreeChooseOne/Img_Lihui13", namea = "未來阿萊塔", dialoguea = "talk_9004400_90044", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "芙露露", dialogueb = "喵喵喵？喵喵？", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1044] = {dialogueid = 1044, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "未來芙露露", dialoguea = "talk_9004401_90044", positionax = "20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "查麗莎", dialogueb = "你是……芙露露？話說……你真的是在誇我嗎？", positionbx = "-20", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1045] = {dialogueid = 1045, picida = "Activity/ThreeChooseOne/Img_Lihui4", namea = "未來查麗莎", dialoguea = "talk_9004402_90044", positionax = "-45", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui5", nameb = "阿萊塔", dialogueb = "站在我的角度，我更想這樣說——請問你是哪位？", positionbx = "0", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1046] = {dialogueid = 1046, picida = "Activity/ThreeChooseOne/Img_Lihui6", namea = "芙露露", dialoguea = "talk_9004403_90044", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui7", nameb = "未來芙露露", dialogueb = "大約只有隊長十分之一的程度噢？不過對於芙露露來說已經是千萬倍的成長了。", positionbx = "-20", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1047] = {dialogueid = 1047, picida = "Activity/ThreeChooseOne/Img_Lihui8", namea = "阿萊塔", dialoguea = "talk_9004404_90044", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui14", nameb = "未來阿萊塔", dialogueb = "哈哈……某種意義上實現了，但實在開心不起來啊……", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1048] = {dialogueid = 1048, picida = "Activity/ThreeChooseOne/Img_Lihui9", namea = "未來查麗莎", dialoguea = "talk_9004405_90044", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui10", nameb = "查麗莎", dialogueb = "別以為你是未來的我，就能想說什麼就說什麼。", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1049] = {dialogueid = 1049, picida = "Activity/ThreeChooseOne/Img_Lihui11", namea = "斯珀絲", dialoguea = "talk_9004406_90044", positionax = "-30", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui12", nameb = "未來查麗莎", dialogueb = "沒人教過你該怎麼和大人說話嗎，小鬼。", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1050] = {dialogueid = 1050, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "光", dialoguea = "talk_9005200_90052", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "red", dialogueb = "……？每次都這麽自我介紹不累嗎？", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1051] = {dialogueid = 1051, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "光", dialoguea = "talk_9005201_90052", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "red", dialogueb = "……你最好還是祈禱他不要被飢渴的女主角們抓住，大家可是都做好了飼養領航的準備的。", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
