[1053] = {dialogueid = 1053, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "光", dialoguea = "talk_9005203_90052", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "不知火", dialogueb = "小光……如果你想的話，也可以稱呼我為媽媽~", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1054] = {dialogueid = 1054, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "光", dialoguea = "talk_9005204_90052", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "不知火", dialogueb = "我是不會在意……領航也不會在意的，對吧？", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
