[1056] = {dialogueid = 1056, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "会长", dialoguea = "talk_9005206_90052", positionax = "0", positionay = "-110", picidb = "0", nameb = "0", dialogueb = "0", positionbx = "0", positionby = "0", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1057] = {dialogueid = 1057, picida = "Activity/ThreeChooseOne/Img_Lihui6", namea = "米夏", dialoguea = "歡迎光臨……客人小姐，您拏著的這些是？", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "赫洛卡", dialogueb = "請問，你這裏能收購魚獲嗎？", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1058] = {dialogueid = 1058, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "赫洛卡", dialoguea = "唉，停職的日子眞難熬啊，每天喫飽了就是睡，閑暇時候只能出去釣釣魚。", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "伊妲", dialogueb = "你這家夥，喫我一槍吧！", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1059] = {dialogueid = 1059, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "D型b2-H", dialoguea = "領航，請下達任務指令。", positionax = "-45", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui5", nameb = "領航", dialogueb = "請問……你是誰？", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1060] = {dialogueid = 1060, picida = "Activity/ThreeChooseOne/Img_Lihui4", namea = "伊妲", dialoguea = "沒想到幽靈事件之後，還有人鑽硏機器人技術。", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "D型b2-H", dialogueb = "幽靈事件……", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1061] = {dialogueid = 1061, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "領航", dialoguea = "這次你又是來添亂的嗎?", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "赫洛卡", dialogueb = "添亂是什麽意思，我這次可是幫領航找到了100%適格率的駕駛員！", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1062] = {dialogueid = 1062, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "米夏", dialoguea = "赫洛卡小姐……駕駛員一定要穿這樣的衣服嗎？", positionax = "0", positionay = "-110", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "赫洛卡", dialogueb = "這不是很合身嘛。", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1063] = {dialogueid = 1063, picida = "Activity/ThreeChooseOne/Img_Lihui5", namea = "領航", dialoguea = "你就是藍山唯一的駕駛員？", positionax = "0", positionay = "-110", picidb = "Activity/ThreeChooseOne/Img_Lihui1", nameb = "米夏", dialogueb = "唯一……感覺好有壓力……", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1064] = {dialogueid = 1064, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "伊斯卡拉（酒保服）", dialoguea = "歡迎光臨篝火，請問您在酒精度方面是傾向於40％左右的還是70％以上的？", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui3", nameb = "领航", dialogueb = "難道這就是卡佳的飲酒文化嗎……", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1065] = {dialogueid = 1065, picida = "Activity/ThreeChooseOne/Img_Lihui2", namea = "叶芙根尼娅（无武器）", dialoguea = "每年冬天的這段日子眞的好閑啊……啊！快起來特維莎，有人找我們了！", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "特薇尔达", dialogueb = "啊——我沒聽到，我什麽都沒聽到——", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1066] = {dialogueid = 1066, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "伊斯卡拉（酒保服）", dialoguea = "總覺得巷子裏剛剛有什麽動靜啊……這个季節還有野貓獃在外面？", positionax = "-45", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui5", nameb = "戈露卡（外套，无臂刀）", dialogueb = "——呼，剛剛眞的好險。", positionbx = "-40", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1067] = {dialogueid = 1067, picida = "Activity/ThreeChooseOne/Img_Lihui3", namea = "领航", dialoguea = "先説好，我這次度假可沒帶什麽多餘的錢。", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui4", nameb = "特薇尔达", dialogueb = "怎麽上來就説這麽掃興的話，我在你那兒就這種形象嗎？", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1068] = {dialogueid = 1068, picida = "Activity/ThreeChooseOne/Img_Lihui1", namea = "伊斯卡拉（酒保服）", dialoguea = "你……這幾年還好嗎，隊長？", positionax = "-20", positionay = "-60", picidb = "Activity/ThreeChooseOne/Img_Lihui2", nameb = "叶芙根尼娅（无武器）", dialogueb = "這句話應該我來問你才對，伊斯卡。", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
[1069] = {dialogueid = 1069, picida = "Activity/ThreeChooseOne/Img_Lihui4", namea = "特薇尔达", dialoguea = "你就是那个導致我的假期取消的麻煩？", positionax = "0", positionay = "-110", picidb = "Activity/ThreeChooseOne/Img_Lihui5", nameb = "戈露卡（外套，无臂刀）", dialogueb = "呃——就我所知确實是？", positionbx = "-60", positionby = "-60", bgm = "41-Maya-now", "0", "0", "0", "0"},
